insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-grammar','Составьте: Даже если диагноз верен, предложенное лечение из него не следует.','["Nawet jeśli diagnoza jest trafna, nie wynika z niej proponowane leczenie.","Trafna diagnoza zawsze dowodzi każdego leczenia.","Leczenie diagnoza z niej nawet wynika."]',0,'Nawet jeśli вводит уступку, а nie wynika отделяет вывод от предпосылки.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-grammar','Составьте: Я принимаю исходные данные, но оспариваю способ их интерпретации.','["Przyjmuję dane wyjściowe, kwestionuję jednak sposób ich interpretacji.","Odrzucam dane, więc zgadzam się z interpretacją.","Dane sposób interpretacji jednak przyjmuję."]',0,'Jednak точно маркирует границу частичного согласия.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-grammar','Która odpowiedź stosuje zasadę życzliwości?','["Jeśli dobrze rozumiem, bronisz priorytetu bezpieczeństwa; różnimy się co do kosztu środka.","Twierdzisz, że koszty nie istnieją.","To absurd i nie warto odpowiadać."]',0,'Ответ точно реконструирует приоритет и локализует разногласие.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-grammar','Gdzie zbudowano chochoła argumentacyjnego?','["Oponent proponuje ograniczyć ruch, więc chce zakazać ludziom wychodzenia z domu.","Oponent proponuje pilotaż ograniczenia ruchu.","Koszt pilotażu wymaga oszacowania."]',0,'Первая версия карикатурно усиливает исходный тезис.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-grammar','Jak wskazać ciężar dowodu?','["To autor tej tezy powinien wykazać związek przyczynowy.","Każdy musi obalić wszystko.","Dowody są zbędne."]',0,'Формулировка связывает доказательную обязанность с конкретным утверждением.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-grammar','Która konkluzja zachowuje zakres zastrzeżenia?','["Argument uzasadnia pilotaż, lecz nie przesądza o wdrożeniu ogólnokrajowym.","Argument dowodzi sukcesu wszędzie.","Nie wynika z niego nic."]',0,'Вывод признаёт силу аргумента, не расширяя её сверх данных.',5,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-quiz','Co znaczy „teza oponenta”?','["тезис оппонента","принцип благожелательности","усиленная версия аргумента"]',0,'„teza oponenta” oznacza: тезис оппонента.',0,true);
