insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-reading-check','Jak Paweł początkowo zniekształcił tezę Marty?','["Uznał, że chce zastąpić bibliotekarzy","Powiedział, że odrzuca automatyzację","Przypisał jej sprzeciw wobec katalogów"]',0,'Он заменил ограниченный тезис утверждением о ненужности профессии.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-reading-check','Co zrobił po prośbie moderatora?','["Uczciwie zrekonstruował i wzmocnił argument","Zmienił temat","Wycofał wszystkie zastrzeżenia"]',0,'Он назвал реальный тезис и добавил сильный пример доступности.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-reading-check','Jaki był rzeczywisty punkt sporny?','["Przejście od szybkości do ogólnej jakości usługi","Istnienie katalogu","Liczba bibliotekarzy"]',0,'Спор касался обоснованности широкого вывода.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-reading-check','Jak Marta odpowiedziała na zastrzeżenie?','["Zawęziła wniosek i zaproponowała audyt","Zignorowała dane","Zażądała natychmiastowego wdrożenia"]',0,'Она ограничила вывод продолжением пилота.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-reading-check','Dlaczego debata stała się użyteczna?','["Przypisano ciężar dowodu konkretnym tezom","Wszyscy natychmiast się zgodzili","Usunięto wszystkie pytania"]',0,'Доказательные обязанности стали точными.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c23-reading-check','Co pokazuje tekst o częściowej zgodzie?','["Może precyzować spór bez rezygnacji ze stanowiska","Zawsze kończy polemikę","Jest oznaką słabości"]',0,'Частичное согласие помогло сузить область разногласия.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c23-tekst','c2-critical-polemics','Критическая полемика','Отвечаем на сильную позицию без упрощения и подмены тезиса','C2',16,'⚖️','["W debacie o automatyzacji bibliotek Marta twierdziła, że system rekomendacji skróci czas poszukiwania książek. Paweł odpowiedział, że jej zdaniem bibliotekarze są zbędni. Marta zaprotestowała: mówiła o wsparciu jednej czynności, nie o zastąpieniu zawodu.","Moderator zatrzymał rozmowę i poprosił Pawła o uczciwą rekonstrukcję stanowiska. Paweł przyznał, że główną tezą jest poprawa dostępności katalogu, a nie redukcja zatrudnienia. Wzmocnił nawet argument Marty, dodając, że narzędzie może pomagać osobom z ograniczoną mobilnością.","Dopiero potem wskazał punkt sporny. Dane z pilotażu pokazywały krótsze wyszukiwanie, ale nie mierzyły jakości wyboru ani ochrony prywatności. Paweł przyjął pierwszą przesłankę, zakwestionował natomiast przejście od szybkości do ogólnej poprawy usługi.","Marta częściowo przyznała mu rację. Zawęziła konkluzję do kontynuacji pilotażu i zaproponowała niezależny audyt rekomendacji. Nie porzuciła swojego stanowiska, lecz oddzieliła to, co już wykazano, od tego, co nadal wymaga dowodu.","Debata nie zakończyła się pełną zgodą, ale stała się użyteczna. Uczestnicy przestali walczyć z uproszczonymi obrazami cudzych poglądów. Zakres sporu zmalał, a ciężar dowodu został przypisany konkretnym tezom, dzięki czemu możliwy stał się następny krok badania."]','{"teza oponenta":{"lemma":"teza oponenta","translation":"тезис оппонента","part_of_speech":"wyrażenie rzeczownikowe"},"zasada życzliwości":{"lemma":"zasada życzliwości","translation":"принцип благожелательности","part_of_speech":"wyrażenie rzeczownikowe"},"argument stalowy":{"lemma":"argument stalowy","translation":"усиленная версия аргумента","part_of_speech":"wyrażenie rzeczownikowe"},"chochoł argumentacyjny":{"lemma":"chochoł argumentacyjny","translation":"соломенное чучело","part_of_speech":"wyrażenie rzeczownikowe"},"punkt sporny":{"lemma":"punkt sporny","translation":"предмет разногласия","part_of_speech":"wyrażenie rzeczownikowe"},"przesłanka":{"lemma":"przesłanka","translation":"предпосылка","part_of_speech":"rzeczownik"},"konkluzja":{"lemma":"konkluzja","translation":"заключение","part_of_speech":"rzeczownik"},"ciężar dowodu":{"lemma":"ciężar dowodu","translation":"бремя доказательства","part_of_speech":"wyrażenie rzeczownikowe"},"przyznać rację częściowo":{"lemma":"przyznać rację częściowo","translation":"частично признать правоту","part_of_speech":"wyrażenie czasownikowe"},"zakwestionować przesłankę":{"lemma":"zakwestionować przesłankę","translation":"оспорить предпосылку","part_of_speech":"wyrażenie czasownikowe"},"odróżnić fakt od oceny":{"lemma":"odróżnić fakt od oceny","translation":"отличить факт от оценки","part_of_speech":"wyrażenie czasownikowe"},"uniknąć nadinterpretacji":{"lemma":"uniknąć nadinterpretacji","translation":"избежать сверхинтерпретации","part_of_speech":"wyrażenie czasownikowe"},"sformułować zastrzeżenie":{"lemma":"sformułować zastrzeżenie","translation":"сформулировать оговорку","part_of_speech":"wyrażenie czasownikowe"},"dochować rzetelności":{"lemma":"dochować rzetelności","translation":"соблюсти добросовестность","part_of_speech":"wyrażenie czasownikowe"},"pozostać przy swoim stanowisku":{"lemma":"pozostać przy swoim stanowisku","translation":"остаться при своей позиции","part_of_speech":"fraza"},"spójność rozumowania":{"lemma":"spójność rozumowania","translation":"связность рассуждения","part_of_speech":"wyrażenie rzeczownikowe"},"zakres zgody":{"lemma":"zakres zgody","translation":"границы согласия","part_of_speech":"wyrażenie rzeczownikowe"},"uczciwa rekonstrukcja":{"lemma":"uczciwa rekonstrukcja","translation":"честная реконструкция","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c23-reading-check"}',59,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
