insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c24-grammar','c2-professional-editing','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Редактируем стиль, логику и информационную структуру сложного текста',14,'✒️','Профессиональная редактура','[["Редакторская диагностика","Сначала определи цель, адресата и основной вывод. Исправляй глобальную структуру до локального стиля: иначе идеально отшлифованное предложение может остаться в ненужном абзаце."],["Минимально достаточное вмешательство","Устраняй двусмысленность, перегрузку и смену регистра, но сохраняй голос автора. Каждое существенное изменение должно иметь объяснимую функцию."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',308,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
