insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-grammar','Составьте: Только после проверки структуры редактор сократил отдельные предложения.','["Dopiero po sprawdzeniu struktury redaktor skrócił poszczególne zdania.","Redaktor przed strukturą skrócił dopiero.","Poszczególne zdania sprawdziły redaktora."]',0,'Dopiero po выстраивает правильную иерархию этапов.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-grammar','Составьте: Чем сложнее тезис, тем яснее должна быть структура текста.','["Im bardziej złożona teza, tym przejrzystsza powinna być struktura tekstu.","Teza złożona, ponieważ struktura mniej jasna.","Tym teza, im struktura tekstu."]',0,'Парная конструкция im..., tym... выражает пропорциональную зависимость.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-grammar','Która wersja usuwa ciężką nominalizację?','["Zespół ocenił ryzyko i zmienił procedurę.","Dokonano przeprowadzenia oceny ryzyka i zmiany procedury.","Ocena dokonania procedury nastąpiła."]',0,'Глаголы ocenił и zmienił возвращают действующее лицо и действие.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-grammar','Jak poprawić hierarchię informacji?','["Najpierw podać główny wniosek, potem dane, które go ograniczają.","Ukryć wniosek w przypisie.","Powtórzyć każdy szczegół trzykrotnie."]',0,'Читатель сначала получает опорный вывод, затем его границы.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-grammar','Która ingerencja zachowuje głos autora?','["Skraca powtórzenie, pozostawiając charakterystyczną metaforę.","Zastępuje wszystkie zdania stylem urzędowym.","Dodaje poglądy redaktora."]',0,'Изменение убирает помеху, но сохраняет индивидуальный образ.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-grammar','Gdzie rejestr jest niespójny?','["Raport przedstawia wyniki, a potem stwierdza: «wynik totalnie rozwala system».","Esej konsekwentnie używa stylu popularnonaukowego.","Dialog świadomie cytuje język potoczny."]',0,'Немотивированный разговорный фрагмент ломает регистр отчёта.',5,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-quiz','Co znaczy „redakcja merytoryczna”?','["содержательная редактура","стилистическая редактура","глобальная связность"]',0,'„redakcja merytoryczna” oznacza: содержательная редактура.',0,true);
