insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-reading-check','Dlaczego tekst był trudny mimo poprawnych zdań?','["Brakowało czytelnego kierunku wywodu","Nie miał żadnych danych","Zawierał błędy ortograficzne"]',0,'Проблема была глобальной, а не локально грамматической.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-reading-check','Co redaktorka zrobiła przed korektą stylu?','["Sporządziła mapę wywodu","Usunęła wszystkie metafory","Zmieniła temat eseju"]',0,'Сначала она диагностировала структуру.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-reading-check','Jak rozluźniła nominalizację?','["Przywróciła podmiot i czasownik","Dodała kolejne rzeczowniki","Usunęła wykonawcę działania"]',0,'Zespół przeprowadził заменяет тяжёлую именную конструкцию.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-reading-check','Po co komentowała większe ingerencje?','["Aby uzasadnić ich funkcję","Aby narzucić własne poglądy","Aby wydłużyć dokument"]',0,'Комментарии делали логику правок прозрачной.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-reading-check','Dlaczego autor odrzucił jedną zmianę?','["Zmieniała stopień pewności wniosku","Nie lubił krótkich zdań","Usuwała błąd ortograficzny"]',0,'Правка искажала эпистемическую силу авторского вывода.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c24-reading-check','Co oznacza redakcja jako projektowanie drogi odbiorcy?','["Porządkowanie przejścia od tezy przez dowody do konsekwencji","Dodawanie ozdobników","Skracanie każdego tekstu o połowę"]',0,'Финал определяет редактуру как управление пониманием структуры.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c24-tekst','c2-professional-editing','Профессиональная редактура','Редактируем стиль, логику и информационную структуру сложного текста','C2',16,'✒️','["Redaktorka otrzymała esej o miejskich ogrodach. Autor zebrał wartościowe dane, lecz pierwszy akapit zawierał historię projektu, metodologię, trzy zastrzeżenia i końcowy wniosek. Każde zdanie było poprawne, a mimo to czytelnik nie wiedział, dokąd prowadzi tekst.","Zamiast od razu wygładzać styl, redaktorka sporządziła mapę wywodu. Odkryła, że najważniejsza teza pojawia się dopiero na końcu: ogrody poprawiają lokalną retencję wody, ale ich efekt zależy od jakości gleby. Przeniosła tę myśl na początek i podporządkowała jej kolejne akapity.","Następnie rozluźniła składnię. Konstrukcję «dokonanie przeprowadzenia pomiarów» zastąpiła zdaniem «zespół przeprowadził pomiary». Usunęła dwa powtórzenia, połączyła sąsiednie przykłady i ujednoliciła naukowy rejestr, nie kasując obrazowej metafory miasta jako gąbki.","Każdą większą ingerencję opatrzyła komentarzem. Wyjaśniła, że przesunięcie akapitu eksponuje związek danych z tezą, a skrót nie usuwa zastrzeżenia, tylko zapobiega redundancji. Autor odrzucił jedną propozycję, ponieważ zmieniała stopień pewności jego wniosku.","Ostateczna wersja była krótsza, lecz nie uboższa. Zachowała głos autora i wszystkie istotne ograniczenia, a jednocześnie prowadziła czytelnika od tezy przez dowody do konsekwencji. Redakcja okazała się nie kosmetyką, ale świadomym projektowaniem drogi odbiorcy przez tekst."]','{"redakcja merytoryczna":{"lemma":"redakcja merytoryczna","translation":"содержательная редактура","part_of_speech":"wyrażenie rzeczownikowe"},"redakcja stylistyczna":{"lemma":"redakcja stylistyczna","translation":"стилистическая редактура","part_of_speech":"wyrażenie rzeczownikowe"},"spójność globalna":{"lemma":"spójność globalna","translation":"глобальная связность","part_of_speech":"wyrażenie rzeczownikowe"},"tok wywodu":{"lemma":"tok wywodu","translation":"ход рассуждения","part_of_speech":"wyrażenie rzeczownikowe"},"hierarchia informacji":{"lemma":"hierarchia informacji","translation":"иерархия информации","part_of_speech":"wyrażenie rzeczownikowe"},"remat":{"lemma":"remat","translation":"рема, новая информация","part_of_speech":"rzeczownik"},"temat zdania":{"lemma":"temat zdania","translation":"тема предложения","part_of_speech":"wyrażenie rzeczownikowe"},"nominalizacja":{"lemma":"nominalizacja","translation":"номинализация","part_of_speech":"rzeczownik"},"rozluźnić składnię":{"lemma":"rozluźnić składnię","translation":"облегчить синтаксис","part_of_speech":"wyrażenie czasownikowe"},"usunąć redundancję":{"lemma":"usunąć redundancję","translation":"устранить избыточность","part_of_speech":"wyrażenie czasownikowe"},"ujednolicić rejestr":{"lemma":"ujednolicić rejestr","translation":"унифицировать регистр","part_of_speech":"wyrażenie czasownikowe"},"wyeksponować wniosek":{"lemma":"wyeksponować wniosek","translation":"выделить вывод","part_of_speech":"wyrażenie czasownikowe"},"przestawić akapit":{"lemma":"przestawić akapit","translation":"переставить абзац","part_of_speech":"wyrażenie czasownikowe"},"zachować głos autora":{"lemma":"zachować głos autora","translation":"сохранить авторский голос","part_of_speech":"wyrażenie czasownikowe"},"uzasadnić ingerencję":{"lemma":"uzasadnić ingerencję","translation":"обосновать вмешательство","part_of_speech":"wyrażenie czasownikowe"},"wersja robocza":{"lemma":"wersja robocza","translation":"рабочая версия","part_of_speech":"wyrażenie rzeczownikowe"},"ślad redakcyjny":{"lemma":"ślad redakcyjny","translation":"редакторский след","part_of_speech":"wyrażenie rzeczownikowe"},"intencja komunikacyjna":{"lemma":"intencja komunikacyjna","translation":"коммуникативное намерение","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c24-reading-check"}',60,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
